		if err != nil {
			phaseManifest.Status = "failed"
			return phaseManifest, out.Artifacts, err
		}
		phaseManifest.Status = "success"
		phaseManifest.Model = out.Model
		phaseManifest.Warnings = append(phaseManifest.Warnings, out.Warnings...)
